"""11-18: Japan, first pack (works before 1868 and up to 1935). Books chosen with the scoring rubric (sel/jp: Shogakukan's
Shinpen Nihon koten bungaku zenshu, Ikezawa's Nihon bungaku zenshu, Ted Mack's modern canon list, Asahi's Heisei 30, awards,
Goodreads, school textbooks, Bokklubben and thegreatestbooks.org), plus the user's additions (Kawabata, Dazai, Akutagawa,
Higashino, Oe, Nosaka) and the six foreign books (second pack, add_jp2.py).
Gutenberg is down, so every book gets scene notes for now; the public-domain ones can take quotations later.
Coordinates come from Commons categories or geotagged Commons photos (coords_jp.json).
Usage: python3 -I add_jp1.py <app_dir> <coords_jp.json>"""
import json, os, sys
sys.path.insert(0, __file__.rsplit("/", 2)[0])
import batchlib as b
APP, CO = sys.argv[1], json.load(open(sys.argv[2], encoding="utf-8"))
b.init(APP, "", "jp", "2026-11-18")
W = b.W

def BK(id, title, title_zh, title_orig, author, author_zh, author_orig, year, pd=True, **kw):
    d = dict(id=id, title=title, title_zh=title_zh, title_orig=title_orig, author=author, author_zh=author_zh, year=year,
             orig_lang=kw.pop("lang", "ja"), public_domain=pd, source_url=None)
    if author_orig:
        d["author_orig"] = author_orig
    d.update(kw)
    return d

def C(pid):
    c = CO[pid]
    return c["lat"], c["lon"], c["st"], c["su"]

def ORIG(pid, name, zh, en_note, zh_note, **kw): return b.ORIG(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PROTO(pid, name, zh, en_note, zh_note, **kw): return b.PROTO(pid, name, zh, *C(pid), en_note, zh_note, **kw)
def PIL(pid, name, zh, en_note, zh_note, ids, **kw): return b.PIL(pid, name, zh, *C(pid), en_note, zh_note, ids, **kw)
